import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import * as api from "../utils/api";

function UserDashboard() {
  const [account, setAccount] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const loadMyAccount = async () => {
      try {
        const data = await api.fetchMyAccount();

        console.log("My account:", data);

        setAccount(data);
      } catch (error) {
        console.error("MY ACCOUNT ERROR:", error);

        setError(
          api.messageFromError(error)
        );
      } finally {
        setLoading(false);
      }
    };

    loadMyAccount();
  }, []);

  /* ================= LOADING ================= */

  if (loading) {
    return (
      <div className="dashboard-container">
        <div className="dashboard-content">
          <div className="eyebrow">
            ONLINE BANKING
          </div>

          <h1>User Dashboard</h1>

          <p className="muted">
            Loading your account...
          </p>
        </div>
      </div>
    );
  }

  /* ================= ERROR ================= */

  if (error) {
    return (
      <div className="dashboard-container">
        <div className="dashboard-content">
          <div className="eyebrow">
            ONLINE BANKING
          </div>

          <h1>User Dashboard</h1>

          <div className="alert error">
            {error}
          </div>
        </div>
      </div>
    );
  }

  /* ================= NO ACCOUNT ================= */

  if (!account) {
    return (
      <div className="dashboard-container">
        <div className="dashboard-content">
          <div className="eyebrow">
            ONLINE BANKING
          </div>

          <h1>User Dashboard</h1>

          <p className="muted">
            No account found.
          </p>
        </div>
      </div>
    );
  }

  /* ================= DASHBOARD ================= */

  return (
    <div className="dashboard-container">

      <div className="dashboard-content">

        <div className="eyebrow">
          ONLINE BANKING
        </div>

        <h1>User Dashboard</h1>

        <p className="muted dashboard-subtitle">
          Manage your account and banking transactions
        </p>

        <div className="account-card">

          <div className="card-top">
            <h2>My Account</h2>

            <span className="badge">
              {account.accountType}
            </span>
          </div>

          <div className="account-details">

            <div className="account-detail-item">
              <span className="detail-label">
                Account Number
              </span>

              <strong>
                {account.accountNumber}
              </strong>
            </div>

            <div className="account-detail-item">
              <span className="detail-label">
                Account Holder
              </span>

              <strong>
                {account.accountHolderName}
              </strong>
            </div>

            <div className="account-detail-item">
              <span className="detail-label">
                Balance
              </span>

              <strong className="dashboard-balance">
                ₹{Number(account.balance || 0).toFixed(2)}
              </strong>
            </div>

            <div className="account-detail-item">
              <span className="detail-label">
                Account Type
              </span>

              <strong>
                {account.accountType}
              </strong>
            </div>

          </div>

          <div className="dashboard-actions">

            <Link
              to={`/accounts/${account.accountId}/deposit`}
            >
              Deposit
            </Link>

            <Link
              to={`/accounts/${account.accountId}/withdraw`}
            >
              Withdraw
            </Link>

            <Link
              to={`/accounts/${account.accountId}/transfer`}
            >
              Transfer
            </Link>

            <Link
              to={`/accounts/${account.accountId}/transactions`}
            >
              Transaction History
            </Link>

          </div>

        </div>

      </div>

    </div>
  );
}

export default UserDashboard;
